import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Qwen Free API — Go Bridge for chat.qwen.ai","description":"A single-file Go bridge exposing chat.qwen.ai (Qwen3.8-Max) behind OpenAI- and Anthropic-compatible endpoints — no keys, real streaming.","frontmatter":{"title":"Qwen Free API — Go Bridge for chat.qwen.ai","description":"A single-file Go bridge exposing chat.qwen.ai (Qwen3.8-Max) behind OpenAI- and Anthropic-compatible endpoints — no keys, real streaming."},"headers":[],"relativePath":"en/projects/qwen-free-api/index.md","filePath":"en/projects/qwen-free-api/index.md"}`),a={name:`en/projects/qwen-free-api/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="qwen-free-api-—-go-bridge-for-chat-qwen-ai" tabindex="-1">Qwen Free API — Go Bridge for chat.qwen.ai <a class="header-anchor" href="#qwen-free-api-—-go-bridge-for-chat-qwen-ai" aria-label="Permalink to “Qwen Free API — Go Bridge for chat.qwen.ai”">​</a></h1><p><strong><a href="https://github.com/Godde3s/qwen-free-api" target="_blank" rel="noreferrer">Qwen Free API</a></strong> is my Go entry in the free-API bridge family: it speaks to <strong>chat.qwen.ai</strong> (Qwen3.8-Max) and exposes it behind <strong>OpenAI- and Anthropic-compatible endpoints</strong>, so any tool that expects those protocols can use Qwen for free.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><ul><li><strong>Single file, zero browser</strong> — like <a href="/Usf/en/projects/glm-free-api/">GLM Free API</a>, no headless Chrome; pure HTTP session handling in Go.</li><li><strong>Dual protocol</strong> — <code>/v1/chat/completions</code> (OpenAI) and <code>/v1/messages</code> (Anthropic) from one binary.</li><li><strong>SSE streaming passthrough</strong> — chunks relay as they arrive, keeping token-by-token latency honest.</li><li><strong>Session hygiene</strong> — guest-token acquisition, rotation and retry baked into the request loop.</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./qwen-free-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8005</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:8005/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;:&quot;qwen-max&quot;,&quot;messages&quot;:[{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;سلام&quot;}],&quot;stream&quot;:true}&#39;</span></span></code></pre></div><p>Same philosophy as the rest of the family: <strong>the bridge must never be the thing that is down</strong> — timeouts, retries and actionable errors, not raw tracebacks. Point <a href="/Usf/en/projects/omnirouter/">OmniRouter</a> at it and Qwen becomes one more upstream in the pool. MIT licensed.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};